import{_ as t,o as a,c as o,ak as n}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Test functions catalog","description":"","frontmatter":{"title":"Test functions catalog","lang":"en-US"},"headers":[],"relativePath":"test-functions.md","filePath":"test-functions.md","lastUpdated":1788701922000}'),s={name:"test-functions.md"};function r(i,e,c,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="test-functions-catalog" tabindex="-1">Test functions catalog <a class="header-anchor" href="#test-functions-catalog" aria-label="Permalink to &quot;Test functions catalog&quot;">​</a></h1><p>The test functions catalog is a <strong>per-project registry of your own page-object methods and helpers</strong>, each stored with the DOM pattern its steps produce. It lets recordings and agents refer to <em>your</em> code instead of raw locators: the <a href="./extension.html">browser extension</a> collapses matched steps in a recording into a call to your function, and an MCP agent can register the functions it writes. The catalog lives in the dashboard, and the extension and MCP tools read from it.</p><h2 id="where-it-lives" tabindex="-1">Where it lives <a class="header-anchor" href="#where-it-lives" aria-label="Permalink to &quot;Where it lives&quot;">​</a></h2><p>A project&#39;s <strong>Test functions</strong> page in the dashboard (<strong>Project → Test functions</strong>). Every entry is scoped to that project, and the <a href="./extension.html#connecting-to-a-piwi-instance">browser extension</a> caches a mapped project&#39;s catalog locally so it can match against it while you record.</p><h2 id="registering-a-function" tabindex="-1">Registering a function <a class="header-anchor" href="#registering-a-function" aria-label="Permalink to &quot;Registering a function&quot;">​</a></h2><p>Four ways in, all landing in the same reviewed entry:</p><ul><li><strong>By hand</strong> — <strong>Add function</strong> and fill in the name, parameters and pattern yourself.</li><li><strong>Paste the source, let AI propose it</strong> — paste a page-object method or helper&#39;s source and a model proposes the name, parameters, and DOM pattern into a <strong>review form you edit before saving</strong>. With <a href="./ai-diagnosis.html">AI</a> configured on the instance, an <strong>Extract</strong> button calls it directly.</li><li><strong>Bring your own AI</strong> — no instance AI, or you&#39;d rather not use it? <strong>Copy prompt for your own AI</strong> copies the full extraction prompt (the rules, the JSON schema, and your pasted code) to paste into any AI chat (ChatGPT, Claude.ai, an IDE assistant). Paste the reply back and it is validated against the exact same schema — no Piwi AI credits spent either way.</li><li><strong>From a coding agent (MCP)</strong> — an MCP-connected agent (Claude Code, Cursor, …) calls the <code>create_test_function</code> <a href="./mcp.html">MCP tool</a> directly, reading the source with its own model. No AI call happens on the server side; the tool only validates and persists.</li></ul><p>Registered entries are edited in place from the same page — the pencil button reopens the form with everything filled in.</p><h2 id="object-parameters" tabindex="-1">Object parameters <a class="header-anchor" href="#object-parameters" aria-label="Permalink to &quot;Object parameters&quot;">​</a></h2><p>A parameter can be typed <strong>object</strong>, for the options-bag argument most helpers take — <code>selectOption(page, { label }, { value })</code>. You list the bag&#39;s keys, and a parameter source then targets one key by name, so a generated call passes <code>{ label: &#39;Country&#39; }</code> rather than a bare string.</p><h2 id="what-extraction-won-t-do" tabindex="-1">What extraction won&#39;t do <a class="header-anchor" href="#what-extraction-won-t-do" aria-label="Permalink to &quot;What extraction won&#39;t do&quot;">​</a></h2><p>Extraction is deliberately conservative. A function that branches on its arguments, loops, or calls other helpers whose source isn&#39;t visible can&#39;t be captured as one fixed pattern — so it comes back with <strong>low confidence and a note</strong> saying what was left out, rather than a confident-looking guess you&#39;d have to catch later.</p><h2 id="using-the-catalog" tabindex="-1">Using the catalog <a class="header-anchor" href="#using-the-catalog" aria-label="Permalink to &quot;Using the catalog&quot;">​</a></h2><ul><li><strong>While recording</strong>, the extension live-ranks which catalog function the steps so far look like, and on <strong>Copy as TypeScript</strong> matched steps collapse into a call to your function; anything unmatched stays as plain locators. The matcher only ever <em>selects among</em> the functions you registered — it never invents one. See the <a href="./extension.html#what-it-does">browser extension</a>.</li><li><strong>Against the current page</strong>, the popup&#39;s <strong>Test functions</strong> checklist scores every function in the active project&#39;s catalog: ready to use here, a partial match, or not found on this page.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./extension.html">Browser extension</a> — records against the catalog and consumes it</li><li><a href="./mcp.html">MCP server</a> — the <code>create_test_function</code> tool</li><li><a href="./ai-diagnosis.html">AI diagnosis</a> — the model the <strong>Extract</strong> button uses</li></ul>',16)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
